const allRoutes=['home','about','recipes','shop','stories','fundraiser','gallery','blog','contact'];
const labels={home:'Home',about:'About',recipes:'Recipes',stories:'Stories',fundraiser:'Fundraiser',gallery:'Gallery',blog:'Journal',contact:'Contact',shop:'Shop'};
const href=s=>'#'+s;
const SHOP_URL=ROOT+'/online-store';
const ext='target="_blank" rel="noopener"';
