/* ---------- the honey (home page only) ---------- */
const reduceMotion=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const isSafari=/^((?!chrome|chromium|android|crios|fxios).)*safari/i.test(navigator.userAgent);
const STILL='assets/honey-still.webp';
function dipper(){
  const media=`<img class="dipper-media" src="${STILL}" alt="">`;
  return `<div class="dipper" aria-hidden="true">${media}</div>`;
}


/* running honey edge: a slowly flowing wavy band with drips that stretch and fall */
function honeyRun(fill='#ffcf3f',below='#ffffff',deep='#efa51b'){
  const W=2880,pts=[];for(let x=0;x<=W;x+=12){const y=17+9*Math.sin(2*Math.PI*x/480)+4*Math.sin(2*Math.PI*x/288+1.3)+2.5*Math.sin(2*Math.PI*x/160+.4);pts.push([x,y.toFixed(1)])}
  const edge=pts.map(([x,y])=>`L${x},${y}`).join(' ');
  const hl=pts.map(([x,y],i)=>`${i?'L':'M'}${x},${(y-7).toFixed(1)}`).join(' ');
  const id='hr'+Math.random().toString(36).slice(2,7);
  const drips=[[7,6.5,0],[19,8,2.6],[33,7,4.1],[48,9,1.2],[61,6.8,3.4],[74,8.4,.6],[88,7.4,2]].map(([l,d,dl],i)=>`<span class="hdrip ${i%2?'thin':''}" style="left:${l}%;--d:${d}s;--dl:${dl}s"><i></i></span>`).join('');
  return `<div class="honey-run" style="--below:${below};--fill:${fill};--deep:${deep}" aria-hidden="true"><div class="hr-track"><svg viewBox="0 0 ${W} 40" preserveAspectRatio="none"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${fill}"/><stop offset=".55" stop-color="${fill}"/><stop offset="1" stop-color="${deep}"/></linearGradient></defs><path d="M0,0 L${W},0 L${W},${pts[pts.length-1][1]} ${pts.slice().reverse().map(([x,y])=>`L${x},${y}`).join(' ')} Z" fill="url(#${id})"/><path d="${hl}" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="2"/></svg></div></div>`;
}
/* ---------- honey drip: inline SVG beneath the dipper ---------- */
const SVGNS='http://www.w3.org/2000/svg';
function buildHoneyDrip(){
  const hero=document.querySelector('.hero');if(!hero)return;
  const dip=hero.querySelector('.dipper');if(!dip)return;
  let svg=hero.querySelector('.honey-drip');
  const hr=hero.getBoundingClientRect(),dr=dip.getBoundingClientRect();
  const w=dr.width;if(!w||!hr.height)return;
  // start inside the drip bulb so the stream necks out of it
  const cx=dr.left-hr.left+w*0.5705, y0=dr.top-hr.top+w*0.672;
  const H=Math.max(40,hr.height-y0)+6, W=Math.max(120,w*0.2), mid=W/2;
  const key=[Math.round(cx),Math.round(y0),Math.round(H),Math.round(W),reduceMotion].join();
  if(svg&&svg.dataset.key===key)return;
  if(!svg){svg=document.createElementNS(SVGNS,'svg');svg.setAttribute('class','honey-drip');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');hero.insertBefore(svg,dip)}
  svg.dataset.key=key;
  svg.setAttribute('viewBox',`0 0 ${W.toFixed(1)} ${H.toFixed(1)}`);
  Object.assign(svg.style,{left:(cx-mid).toFixed(1)+'px',top:y0.toFixed(1)+'px',width:W.toFixed(1)+'px',height:H.toFixed(1)+'px'});
  const neck=Math.max(12,w*0.034), body=Math.max(5,w*0.0165), tail=Math.max(4,w*0.013), N=46, neckLen=Math.max(30,w*0.06);
  const width=(y,ph)=>{const n=Math.min(1,y/neckLen);const e=1-Math.pow(1-n,3);let base=neck+(body-neck)*e;const t=y/H;base=base+(tail-body)*Math.max(0,(t-0.15)/0.85);
    return base*(1+0.14*Math.sin(t*26-ph)*Math.min(1,y/(neckLen*1.3)))};
  const sway=(y,ph)=>0;
  const shape=(ph)=>{const L=[],R=[];for(let i=0;i<=N;i++){const y=i/N*H;const hw=width(y,ph)/2,sx=sway(y,ph);L.push([mid+sx-hw,y]);R.push([mid+sx+hw,y])}
    const f=p=>p[0].toFixed(2)+' '+p[1].toFixed(2);
    let d='M'+f(L[0]);for(let i=1;i<L.length;i++){const p=L[i-1],q=L[i];d+=' Q'+f(p)+' '+((p[0]+q[0])/2).toFixed(2)+' '+((p[1]+q[1])/2).toFixed(2)}
    d+=' L'+f(L[L.length-1])+' L'+f(R[R.length-1]);const Rr=R.slice().reverse();for(let i=1;i<Rr.length;i++){const p=Rr[i-1],q=Rr[i];d+=' Q'+f(p)+' '+((p[0]+q[0])/2).toFixed(2)+' '+((p[1]+q[1])/2).toFixed(2)}
    return d+' L'+f(R[0])+'Z'};
  const shine=(ph)=>{let d='';for(let i=0;i<=N;i++){const y=neckLen*0.6+i/N*(H-neckLen*0.6);d+=(i?'L':'M')+(mid+sway(y,ph)-width(y,ph)*0.2).toFixed(2)+' '+y.toFixed(2)+' '}return d};
  const P=Math.PI,phases=[0,P/2,P,1.5*P,2*P];
  const ripple=(vals)=>reduceMotion?'':`<animate attributeName="d" dur="1.6s" repeatCount="indefinite" calcMode="linear" values="${vals.join(';')}"/>`;
  const anim=(vals,dur)=>reduceMotion?'':`<animate attributeName="d" dur="${dur}s" repeatCount="indefinite" calcMode="spline" keySplines="${Array(vals.length-1).fill('.37 0 .63 1').join(';')}" values="${vals.join(';')}"/>`;
  const r=body*0.95, sy=neckLen*1.2;
  const drop=reduceMotion?'':`<g opacity="0"><path d="M${mid} ${-r*1.7} C${mid+r*0.95} ${-r*0.5} ${mid+r*1.15} ${r*0.9} ${mid} ${r*1.2} C${mid-r*1.15} ${r*0.9} ${mid-r*0.95} ${-r*0.5} ${mid} ${-r*1.7}Z" fill="url(#hdGrad)"/><circle cx="${mid-r*0.35}" cy="${-r*0.15}" r="${r*0.3}" fill="#fff6d0" opacity=".8"/>
      <animateTransform attributeName="transform" type="translate" dur="9s" begin="2s" repeatCount="indefinite" calcMode="spline" keyTimes="0;.25;.6;1" keySplines=".4 0 .6 1;.6 0 1 .6;0 0 1 1" values="0 ${sy};0 ${sy+8};0 ${H+20};0 ${H+20}"/>
      <animate attributeName="opacity" dur="9s" begin="2s" repeatCount="indefinite" keyTimes="0;.1;.58;.6;1" values="0;1;1;0;0"/></g>`;
  svg.innerHTML=`<defs>
    <linearGradient id="hdGrad" x1="0" x2="1" y1="0" y2="0"><stop offset="0" stop-color="#a65d08"/><stop offset=".2" stop-color="#df900e"/><stop offset=".42" stop-color="#ffc02a"/><stop offset=".52" stop-color="#ffe7a4"/><stop offset=".66" stop-color="#f4aa16"/><stop offset="1" stop-color="#ad6309"/></linearGradient>
    <linearGradient id="hdFade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".001" stop-color="#fff" stop-opacity="1"/></linearGradient>
    <mask id="hdMask"><rect x="0" y="0" width="${W}" height="${H}" fill="url(#hdFade)"/></mask>
    <filter id="hdGlow" x="-60%" y="-5%" width="220%" height="110%"><feGaussianBlur stdDeviation="4"/></filter></defs>
  <g mask="url(#hdMask)"><g transform="translate(${mid} 0)"><g>${reduceMotion?'':'<animateTransform attributeName="transform" type="skewX" dur="6s" repeatCount="indefinite" calcMode="spline" keyTimes="0;.25;.5;.75;1" keySplines=".37 0 .63 1;.37 0 .63 1;.37 0 .63 1;.37 0 .63 1" values="0;2.4;0;-2.4;0"/>'}<g transform="translate(${-mid} 0)">
    <path d="${shape(0)}" fill="#ffb81f" opacity=".28" filter="url(#hdGlow)">${ripple(phases.map(shape))}</path>
    <path d="${shape(0)}" fill="url(#hdGrad)">${ripple(phases.map(shape))}</path>
    <path d="${shine(0)}" fill="none" stroke="#fff4c8" stroke-width="${Math.max(1.5,body*0.3).toFixed(2)}" stroke-linecap="round" stroke-dasharray="46 104" opacity="1">${reduceMotion?'':'<animate attributeName="stroke-dashoffset" from="0" to="-150" dur="1.1s" repeatCount="indefinite"/>'}</path><path d="${shine(0)}" fill="none" stroke="#fffbe8" stroke-width="${Math.max(.8,body*0.16).toFixed(2)}" stroke-linecap="round" stroke-dasharray="18 186" opacity="1" transform="translate(${(body*0.32).toFixed(2)} 0)">${reduceMotion?'':'<animate attributeName="stroke-dashoffset" from="0" to="-204" dur="1.7s" repeatCount="indefinite"/>'}</path></g></g></g>
  </g>`;
}

