/* ---------- home: six sections ---------- */
const hero=()=>`<section class="hero">${dipper()}<div class="container hero-content"><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span>The Pride of Alabama · Est. 1928</span><h1><span class="script-accent">More than syrup.</span>Every jar holds a <em>memory.</em></h1><p>For nearly a hundred years, a jar of Golden Eagle has had a place at the family table. Still made, and still hand-tightened, in Fayette, Alabama.</p><div class="hero-actions"><a class="btn" href="#shop">Bring a jar home</a><a class="btn ghost" href="#recipes">Open the recipe box</a></div></div></div></section><div class="honey-band"><div class="ticker"><div class="ticker-track">${(()=>{const r=['Golden Eagle Syrup','Since 1928','Made in Fayette, Alabama','Hand-tightened, every jar','Family-run','The Pride of Alabama'].map(w=>`<span>${w}</span><b>✦</b>`).join('');return r+r})()}</div></div></div>`+honeyRun('#ffcf3f','#ffffff');

const pie=()=>`<section class="section pie-section"><div class="container section-grid"><a class="pie-visual reveal" href="#recipes" data-open="0" aria-label="Open the Golden Eagle Pecan Pie recipe"><span class="gingham"></span><span class="pie-photo"><img src="assets/pie-slice-photo.jpg" alt="A slice of Golden Eagle pecan pie on a white plate" loading="lazy"></span><span class="pie-badge">sweet since<b>1928</b></span><span class="recipe-index"><span class="tape"></span><span class="ri-head"><small>From the recipe box</small><strong>Golden Eagle Pecan Pie</strong></span><span class="hand ri-lines"><span>3 eggs · ½ cup sugar</span><span>1 cup Golden Eagle Syrup</span><span>1 cup chopped pecans</span><span>bake 385° · about an hour ♡</span></span></span></a><div class="reveal"><span class="kicker">The one everyone asks about</span><h2>Pass the pie, please.</h2><p>Every family has that one dessert. For generations of Alabama tables, it's a pecan pie made golden with a jar of Golden Eagle. The recipe is right here, ready to pass down.</p><div class="pie-actions"><a class="btn navy" href="#recipes" data-open="0">Get the pie recipe</a><a class="text-link" href="#recipes">Browse the recipe box →</a></div></div></div></section>`;

const moreRecipes=()=>`<section class="section cream wave-top" style="--wave:#f8f4ea"><div class="container"><div class="section-head reveal"><div><span class="kicker">More from the recipe box</span><h2>Sweet, savory &amp; Sunday-ready.</h2></div><a class="text-link" href="#recipes">See every recipe →</a></div><div class="mini-recipes">${recipes.slice(1).map((r,i)=>`<a class="mini-recipe reveal" href="#recipes" data-open="${i+1}">${photoOrCard(r)}<span class="mini-body"><small>${r.category}</small><h3>${r.short}</h3><span class="food-link">Get the recipe →</span></span></a>`).join('')}</div></div></section>`;

const history=()=>`<section class="section history town-bg"><div class="container section-grid"><figure class="polaroid has-sticker reveal"><img src="assets/photos/manufacturers-wall.jpg" alt="Golden Eagle Syrup Manufacturers sign with eagle on the Fayette factory wall" loading="lazy"><figcaption>The sign on 1st Avenue</figcaption><a class="sl-sticker" href="${SOUTHERN_LIVING}" ${ext} aria-label="As seen in Southern Living: read the story"><img src="assets/sl-monogram.png" alt=""><span>As seen in</span></a></figure><div class="reveal"><span class="kicker">Our story</span><h2>It all started behind the Pattersons' house.</h2><p>Victor and Lucy Patterson made their first jars in 1928, in a little wood-frame building behind their home. In 1944 they moved into the downtown Fayette factory, and that's where Golden Eagle is still made today.</p><a class="btn navy" href="#about">Read our story</a><div class="press-note"><span>As featured in</span><a href="${SOUTHERN_LIVING}" ${ext}><img class="sl-wm" src="assets/sl-wordmark.png" alt="Southern Living"><em>Read the story ↗</em></a><a href="${THIS_IS_AL}" ${ext}><b><small>THIS IS</small> ALABAMA</b><em>Watch the video ↗</em></a></div></div></div></section>`;

