const PH='assets/photos/';
const about=()=>`<section class="about-hero"><img class="ah-img" src="${PH}august-1955.jpg" alt="The Golden Eagle Table Syrup factory in Fayette, Alabama, August 1955"><div class="ah-shade"></div><div class="container ah-inner"><span class="kicker light">Our story · Fayette, Alabama</span><h1>Almost a century of golden goodness.</h1><p>Two people, one family recipe, and a building on 1st Avenue that still turns out every jar by hand.</p><span class="ah-cap">The factory, August 1955</span></div></section>
<section class="section white tl-section"><div class="container"><div class="center reveal tl-intro"><span class="kicker">How it all happened</span><h2>From a backyard to 1st Avenue.</h2></div>
<div class="timeline2" id="tl2"><span class="tl-rail"><span class="tl-fill"></span></span>
<article class="tl-row reveal"><div class="tl-text"><span class="tl-year">1928</span><h3>It started behind the house.</h3><p>Victor and Lucy Patterson made the first jars of Golden Eagle in a small wood-frame building behind their family home in Fayette.</p></div><span class="tl-dot"></span><figure class="tl-photo founders"><img src="${PH}founders.jpg" alt="Vintage portrait of founders Victor and Lucy Patterson" loading="lazy"><figcaption>Mr. &amp; Mrs. V. S. Patterson, Sr.</figcaption></figure></article>
<article class="tl-row flip reveal"><div class="tl-text"><span class="tl-year">1944</span><h3>Moving downtown.</h3><p>As word spread and demand grew, production moved into a factory in downtown Fayette. Golden Eagle has called that building home ever since.</p></div><span class="tl-dot"></span><figure class="tl-photo"><img src="${PH}august-1955.jpg" alt="The Golden Eagle factory in 1955" loading="lazy"><figcaption>1st Avenue, 1955</figcaption></figure></article>
<article class="tl-row reveal"><div class="tl-text"><span class="tl-year">Today</span><h3>Still golden, still by hand.</h3><p>Still family-run, in the same Fayette building, and every lid is still hand-tightened. The founders' commitment to quality carries forward, one jar at a time.</p></div><span class="tl-dot"></span><figure class="tl-photo"><img src="${PH}hand-tightening.jpg" alt="Temple Bowling hand-tightening a jar of Golden Eagle" loading="lazy" style="object-position:50% 25%"><figcaption>Temple Bowling, tightening by hand</figcaption></figure></article>
</div></div></section>
<section class="people2"><img src="${PH}team.jpg" alt="The Golden Eagle team" loading="lazy"><div class="container"><div class="p2-card reveal"><span class="kicker">The people behind the jar</span><h2>Family-run, still.</h2><p>Martha Kimbrell, Annie Wright, Temple Bowling, Kimberly Bowling, Willard Tyner, John Blevins and Rivers Bowling keep the jars coming in Fayette.</p><figure class="p2-inset"><img src="${PH}families.jpg" alt="The Bowling and Blevins families at Golden Eagle headquarters" loading="lazy"><figcaption>The Bowling &amp; Blevins families</figcaption></figure></div></div></section>
<section class="section scrapbook"><div class="container"><div class="section-head reveal"><div><span class="kicker">From the archive</span><h2>Cans, signs &amp; a whole lot of history.</h2></div></div><div class="sb-board">
<figure class="sb-item s1 reveal"><span class="tape"></span><img src="${PH}vintage-cans-2.jpg" alt="Original vintage Golden Eagle table syrup can" loading="lazy"><figcaption>An original Table Syrup can</figcaption></figure>
<figure class="sb-item s2 reveal"><span class="tape"></span><img src="${PH}mural.jpg" alt="Golden Eagle mural on the Fayette factory wall" loading="lazy"><figcaption>The factory mural, painted by Missy Miles</figcaption></figure>
<figure class="sb-item s3 reveal"><span class="tape"></span><img src="${PH}vintage-cans-1.jpg" alt="Early Golden Eagle can label" loading="lazy"><figcaption>V. S. Patterson's early label</figcaption></figure>
<figure class="sb-item s4 reveal"><span class="tape"></span><img src="${PH}bottling-line.jpg" alt="Jars on the Golden Eagle bottling line" loading="lazy"><figcaption>Jars on the line</figcaption></figure>
<span class="sb-note reveal"><span class="hand">Same recipe,<br>same building,<br>since 1944 ♡</span></span>
</div></div></section>
<section class="jar2"><div class="container"><div class="jar2-head reveal"><span class="kicker light">What's in the jar</span><h2>Four ingredients.<br><em>One unforgettable blend.</em></h2></div><div class="jar2-stage"><ul class="jar2-col left"><li class="reveal"><span class="j2-num">01</span><span class="j2-name">Corn syrup</span><span class="j2-line"></span></li><li class="reveal"><span class="j2-num">02</span><span class="j2-name">Cane sugar syrup</span><span class="j2-line"></span></li></ul><div class="jar2-jar reveal"><span class="jar2-glow"></span><img src="${PH}jar-15oz-cutout.png" alt="A 15 oz jar of Golden Eagle syrup" loading="lazy"><span class="jar2-shadow"></span></div><ul class="jar2-col right"><li class="reveal"><span class="j2-line"></span><span class="j2-num">03</span><span class="j2-name">Cane molasses</span></li><li class="reveal"><span class="j2-line"></span><span class="j2-num">04</span><span class="j2-name">Pure honey</span></li></ul></div><div class="jar2-foot reveal"><p>Blended the same way it always has been, and hand-tightened in Fayette.</p><a class="btn" href="#shop">Bring a jar home</a></div></div></section>
<section class="section about-end"><div class="container end-grid"><div class="news-card reveal"><img class="news-mono" src="assets/sl-monogram.png" alt=""><div class="news-body"><span class="kicker">In the news</span><img class="news-wm" src="assets/sl-wordmark.png" alt="Southern Living"><p>Southern Living shared the Golden Eagle story with readers across the South.</p><div class="pie-actions"><a class="btn navy" href="${SOUTHERN_LIVING}" ${ext}>Read the story ↗</a><a class="text-link" href="${THIS_IS_AL}" ${ext}>This Is Alabama ↗</a></div></div></div><div class="visit-card reveal"><span class="tape"></span><span class="kicker">Come say hello</span><h2>Find us in Fayette.</h2><p>205 1st Avenue SE<br>Fayette, Alabama 35555<br>(205) 932-5294</p><div class="pie-actions"><a class="btn navy" href="https://maps.google.com/?q=205+1st+Avenue+SE+Fayette+Alabama+35555" ${ext}>Get directions ↗</a></div></div></div></section>`+nextNav('about');

