const recipePage=()=>`<section class="rc-hero"><div class="container rc-grid"><div class="rc-copy"><span class="kicker">The recipe box</span><h1>Recipes worth <em>passing down.</em></h1><p>Golden Eagle family favorites, from the pie everyone asks about to a glaze for the holiday ham. Tick off ingredients as you go, and copy any list for your grocery run.</p><a class="btn navy" href="#recipes" data-open="0">Start with the pecan pie</a></div><figure class="rc-photo"><img src="assets/pecan-pie-whole.jpg" alt="A Golden Eagle pecan pie with a slice served on a white plate"><span class="rc-tag"><span class="hand">the one everyone<br>asks about ♡</span></span></figure></div></section>`+`<section class="content-shell recipes-shell"><div class="tab-row" role="group" aria-label="Recipe categories">${['All','Desserts','Savory'].map((c,i)=>`<button type="button" class="filter tab ${i?'':'active'}" data-filter="${c}">${c}</button>`).join('')}</div><div class="recipe-grid">${recipes.map((r,ri)=>`<article class="recipe-card reveal" data-category="${r.category}">${photoOrCard(r,'recipe-art')}<div class="recipe-body"><small>${r.category}</small><h3>${r.title}</h3><p>${r.desc}</p><ul class="chips">${recipeMeta[r.key].map(m=>`<li>${m}</li>`).join('')}</ul><details><summary>View full recipe</summary><div class="rec-head"><h4>Ingredients</h4><button type="button" class="copy-btn" data-copy="${ri}">Copy list</button></div><ul class="checklist">${r.ingredients.map((x,j)=>`<li><label><input type="checkbox"><span>${x}</span></label></li>`).join('')}</ul><h4>Directions</h4><p>${r.instructions}</p></details></div></article>`).join('')}</div><p class="fineprint">Recipes adapted from Golden Eagle’s published recipe collection.</p></section><section class="kitchen"><div class="container kitchen-grid"><figure class="kitchen-photo reveal"><img src="assets/photos/kitchen.jpg" alt="A vintage kitchen with a white enamel stove, subway tile and a checkerboard floor" loading="lazy"></figure><div class="kitchen-copy reveal"><span class="kicker">From the kitchen</span><h2>Where the good stuff happens.</h2><p>Warm bread on the counter and a skillet on the stove. Every recipe in the box was made for a kitchen like this one.</p><a class="btn navy" href="#shop">Stock your pantry</a></div></div></section>`+nextNav('recipes');

