const jarSVG=(size,six)=>{const one=(x,s)=>`<g transform="translate(${x} ${s===30?0:16}) scale(${s===30?1:.84})" transform-origin="40 150"><rect x="14" y="8" width="52" height="16" rx="3" fill="#ffca32" stroke="#d99a12" stroke-width="2"/><path d="M10 30 Q10 24 18 24 H62 Q70 24 70 30 V140 Q70 150 60 150 H20 Q10 150 10 140Z" fill="url(#amb)" stroke="#9b5a07" stroke-width="2"/><rect x="10" y="62" width="60" height="46" fill="${ink}"/><text x="40" y="82" text-anchor="middle" font-family="Georgia,serif" font-size="11" font-weight="700" fill="#ffca32">GOLDEN</text><text x="40" y="96" text-anchor="middle" font-family="Georgia,serif" font-size="11" font-weight="700" fill="#ffca32">EAGLE</text><path d="M18 36 V56" stroke="#fff6c8" stroke-width="5" stroke-linecap="round" opacity=".55"/></g>`;
 const defs='<defs><linearGradient id="amb" x1="0" x2="1"><stop offset="0" stop-color="#a95f08"/><stop offset=".45" stop-color="#f0a512"/><stop offset="1" stop-color="#b86b0c"/></linearGradient></defs>';
 const jars=six?[-34,40,114].map((x,i)=>one(x,size)).join(''):[0,74].map(x=>one(x+3,size)).join('');
 return `<svg viewBox="${six?'-38 0 230 160':'-2 0 160 160'}" class="p-svg">${defs}${jars}<text x="75" y="0" ></text></svg><span class="p-tag">${size} oz${six?' · ×6':' · ×2'}</span>`};
