 const bodies={tee:'M40 20 L60 14 Q70 24 80 14 L100 20 L124 44 L108 58 L100 50 V140 H40 V50 L32 58 L16 44Z',long:'M40 20 L60 14 Q70 24 80 14 L100 20 L120 40 L132 120 L116 124 L104 64 V140 H36 V64 L24 124 L8 120 L20 40Z',hoodie:'M40 22 L56 14 Q70 34 84 14 L100 22 L120 42 L132 120 L116 124 L104 64 V140 H36 V64 L24 124 L8 120 L20 42Z',onesie:'M46 20 L60 14 Q70 22 80 14 L94 20 L114 40 L102 52 L96 46 V112 Q96 122 86 126 L78 140 H62 L54 126 Q44 122 44 112 V46 L38 52 L26 40Z'};
