function productArt(spec){const [k,a,b,c]=spec.split(':');
 if(k==='store')return `<img class="store-img ${c||''}" src="assets/${a}" alt="" loading="lazy">${b?`<span class="p-tag">${b}</span>`:''}`;
 if(k==='jarphoto')return `<img class="jar-photo" src="assets/photos/jar-15oz-cutout.png" alt="" loading="lazy"><span class="p-tag">${a}</span>`;
 if(k==='jar'){const six=a.includes('x6');return jarSVG(parseInt(a),six)}
 if(k==='photo')return `<img src="assets/${a}" alt="" loading="lazy">`;
 if(k==='bag')return bagSVG(a,b);if(k==='plate')return plateSVG();if(k==='store:store/koozie.jpg')return koozieSVG();if(k==='minipies')return miniPiesSVG();
 if(k==='hat')return hatSVG(a);return shirt(a,k)}
const productCard=([cat,name,price,url,art,note])=>`<article class="product reveal" data-cat="${cat}"><div class="p-art ${art.startsWith('photo')||art.startsWith('store')?'is-photo':''} ${art.endsWith(':jar')?'is-jar':''} ${art.endsWith(':contain')?'is-contain':''}">${productArt(art)}</div><div class="p-body"><h3>${name}</h3>${note?`<p>${note}</p>`:''}<div class="p-foot"><span class="price">${money(price)}</span><a class="buy" href="#contact">Order →</a></div></div></article>`;
const shopHeroArt=`<figure class="mini-pol shop-pol"><img src="assets/photos/jars-on-wood.jpg" alt=""><figcaption>the pride of Alabama</figcaption></figure><span class="price-tag"><span class="hand">from</span><b>$3</b></span>`;
const shop=()=>pageHero('The general store','Bring a little Alabama home.','Syrup by the pair or the case, pecan pies, caramel corn, granola, and a few things to wear.',shopHeroArt)+`<section class="content-shell shop-shell"><div class="tab-row shop-tabs" role="group" aria-label="Product categories"><button type="button" class="filter tab active" data-shop="all">All</button>${shopCats.map(([k,t])=>`<button type="button" class="filter tab" data-shop="${k}">${t}</button>`).join('')}</div>${shopCats.map(([k,t,d])=>`<section class="shop-cat" data-catsec="${k}">${k==='apparel'?'<div class="apparel-banner"><img src="assets/store/apparel-cat.jpg" alt="Golden Eagle apparel modeled in front of a brick wall" loading="lazy"><div><span class="kicker">Wear it proud</span><h3>Tees, hats &amp; sweatshirts for every Golden Eagle fan.</h3></div></div>':''}<div class="cat-head"><h2>${t}</h2><span class="hand">${d}</span></div><div class="product-grid">${products.filter(p=>p[0]===k).map(productCard).join('')}</div></section>`).join('')}<div class="shop-callout reveal"><div><span class="kicker">Raising money?</span><h3>Caramel corn, mini pies &amp; granola make sweet fundraisers.</h3></div><a class="btn navy" href="#fundraiser">See the fundraiser program</a></div><p class="fineprint">Prices as listed on the official Golden Eagle store on November 22, 2026, and may have changed. Product photos are from the official store; shirts without a store photo are shown as illustrations.</p></section>`+nextNav('shop');

const fundraiser=()=>pageHero('Fundraising','Fundraising, the golden way.','Golden Eagle runs a fundraiser program for schools, PTOs, teams and clubs, with treats folks are glad to buy.',`<div class="flyer"><span class="pin"></span><span class="hand big">Sweet<br>fundraiser!</span><span class="hand">caramel corn · mini pies<br>&amp; granola ♡</span></div>`)+`<section class="section white"><div class="container"><div class="section-head reveal"><div><span class="kicker">What you can sell</span><h2>Three crowd-pleasers.</h2></div></div><div class="product-grid three">${products.filter(p=>['Case of Mini Pecan Pies','12-Pack Caramel Corn','Golden Eagle Granola'].includes(p[1])).map(productCard).join('')}</div><p class="fineprint">Store prices shown for reference. Fundraiser pricing, minimums and terms come from the Golden Eagle team.</p></div></section><section class="section cream"><div class="container"><div class="section-head reveal"><div><span class="kicker">How it works</span><h2>Three sweet steps.</h2></div></div><ol class="steps">${[['Send an inquiry','Tell the Golden Eagle team about your school, PTO, team or club and when you want to sell.'],['Pick your treats','Choose from caramel corn, mini pecan pies and granola, all made with Golden Eagle.'],['Place a group order','Collect orders from supporters and send in one group order with the Golden Eagle team.']].map(([h,p],i)=>`<li class="reveal"><span class="step-num">${i+1}</span><h3>${h}</h3><p>${p}</p></li>`).join('')}</ol></div></section><section class="section white"><div class="container section-grid"><div class="reveal"><span class="kicker">Made for</span><h2>Good causes close to home.</h2><ul class="idea-list"><li>Schools &amp; PTOs</li><li>Sports teams &amp; boosters</li><li>Clubs &amp; community groups</li></ul><div class="pie-actions"><a class="btn navy" href="#contact">Start an inquiry →</a><a class="text-link" href="#contact">Or call the Fayette team</a></div></div><figure class="polaroid tilt-r reveal"><img src="assets/photos/fundraiser-group.jpg" alt="Collage of school teams, cheerleaders and bands" loading="lazy"><figcaption>For schools, teams &amp; clubs</figcaption></figure></div></section>`+nextNav('fundraiser');


const merchPicks=[['Golden Eagle Corduroy Hat',28,'store/corduroy-hat.jpg'],['Front & Back Color Logo – Yellow',25,'store/tee-yellow.jpg'],['Keep It Golden Koozie',3,'store/koozie.jpg'],['Light Blue Long Sleeve',25,'store/longsleeve-blue.jpg'],['Golden Eagle Syrup Label License Plate',15,'store/plate.jpg']];
const merchShow=(title='Wear it. Gift it. Pour it.',kicker='From the general store')=>`<section class="merch"><div class="container"><div class="merch-head"><div><span class="kicker light">${kicker}</span><h2>${title}</h2><p>Hats, tees, koozies and a license plate for the truck, plus the syrup that started it all.</p></div><a class="btn" href="#shop">Visit the shop →</a></div><div class="merch-row">${merchPicks.map(([n,p,img])=>{const prod=products.find(x=>x[1]===n);return `<a class="merch-card" href="#shop"><span class="merch-img"><img src="assets/${img}" alt="${n}" loading="lazy"></span><span class="merch-name">${n.replace('Golden Eagle Syrup Label ','')}</span><span class="merch-price">$${p}</span></a>`}).join('')}</div></div></section>`;
/* ---------- chrome ---------- */
const footer=()=>`<footer class="footer"><div class="container"><div class="footer-grid"><div><img class="footer-logo" src="assets/official-logo.png" alt="Golden Eagle Syrup"><p>The Pride of Alabama.<br>Made in Fayette, Alabama.</p><a href="#shop" class="btn">Shop Golden Eagle</a></div><div><h3>Explore</h3>${allRoutes.map(k=>`<div><a href="${href(k)}">${labels[k]}</a></div>`).join('')}</div><div><h3>Find us</h3><p>205 1st Avenue SE<br>Fayette, AL 35555<br><a href="tel:+12059325294">(205) 932-5294</a></p></div></div><div class="footer-bottom">Unofficial website redesign concept by Lindsay Morton · Not affiliated with Golden Eagle Syrup · Shop links open the company’s existing store.</div></div></footer>`;

const header=p=>`<a class="skip" href="#main">Skip to content</a><header class="header"><div class="header-inner"><a class="brand" href="#home" aria-label="Golden Eagle home"><img src="assets/official-logo.png" alt="Golden Eagle Syrup, Pride of Alabama"></a><button class="menu-toggle" aria-label="Toggle menu" aria-expanded="false">☰</button><nav class="nav" aria-label="Main navigation">${routes.map(k=>`<a class="${k===p?'active':''}" href="${href(k)}">${labels[k]}</a>`).join('')}</nav><a class="btn shop-pill ${p==='shop'?'on':''}" href="#shop">Shop</a></div></header>`;

const renderers={home,about,recipes:recipePage,shop,stories:storiesPage,fundraiser,gallery,blog,contact};
let io,openRecipe=null;
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('[data-open]');if(a)openRecipe=+a.dataset.open});
function render(){
  const raw=location.hash.replace('#','');
  if(raw==='main')return;
  const p=renderers[raw]?raw:'home';
  document.getElementById('app').innerHTML=header(p)+`<main id="main" class="page-${p}">${renderers[p]()}</main>`+footer();
  document.title=`${labels[p]} | Golden Eagle Syrup concept`;
  document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const n=document.querySelector('.nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))});
  document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('[data-category]').forEach(el=>el.style.display=btn.dataset.filter==='All'||el.dataset.category===btn.dataset.filter?'':'none')}));
  document.querySelectorAll('video.dipper-media').forEach(v=>{v.muted=true;const pr=v.play();if(pr&&pr.catch)pr.catch(()=>{})});
  if(io)io.disconnect();
  const els=document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window&&!reduceMotion){io=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target)}}),{threshold:.12,rootMargin:'0px 0px -40px 0px'});els.forEach(el=>io.observe(el))}else els.forEach(el=>el.classList.add('in'));
  window.scrollTo({top:0,behavior:'instant'});
  document.querySelectorAll('[data-copy]').forEach(btn=>btn.addEventListener('click',()=>{const r=recipes[+btn.dataset.copy];const txt=r.title+'\n'+r.ingredients.map(x=>'- '+x).join('\n');const done=()=>{btn.textContent='Copied ✓';setTimeout(()=>btn.textContent='Copy list',1800)};try{navigator.clipboard.writeText(txt).then(done,()=>{btn.textContent='Copy blocked'})}catch(e){btn.textContent='Copy blocked'}}));
  const lb=document.querySelector('.lightbox');
  if(lb){const close=()=>{lb.hidden=true};const open=i=>{const [src,cap]=galleryItems[i];lb.querySelector('img').src='assets/'+src;lb.querySelector('img').alt=cap;lb.querySelector('figcaption').textContent=cap;lb.querySelector('.lb-pol').classList.toggle('is-dish',galleryItems[i][2]==='dish');lb.hidden=false;lb.querySelector('.lb-close').focus()};
    document.querySelectorAll('[data-lightbox]').forEach(f=>{f.addEventListener('click',()=>open(+f.dataset.lightbox));f.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(+f.dataset.lightbox)}})});
    lb.addEventListener('click',e=>{if(e.target===lb||e.target.classList.contains('lb-close'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})}
  document.querySelectorAll('[data-shop]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-shop]').forEach(b=>b.classList.toggle('active',b===btn));const k=btn.dataset.shop;document.querySelectorAll('[data-catsec]').forEach(sec=>sec.style.display=k==='all'||sec.dataset.catsec===k?'':'none')}));
  if(p==='about'){const tl=document.getElementById('tl2');if(tl){const f=tl.querySelector('.tl-fill');const upd=()=>{if(!document.body.contains(tl))return;const r=tl.getBoundingClientRect();const v=Math.min(1,Math.max(0,(innerHeight*.6-r.top)/r.height));f.style.transform='scaleY('+v+')';tl.querySelectorAll('.tl-row').forEach(row=>{const rr=row.getBoundingClientRect();row.classList.toggle('lit',rr.top<innerHeight*.6)})};window.removeEventListener('scroll',window.__tlUpd||(()=>{}));window.__tlUpd=upd;addEventListener('scroll',upd,{passive:true});upd()}}
  document.querySelectorAll('.rc-chip').forEach(ch=>ch.addEventListener('click',e=>{if(location.hash==='#recipes'){e.preventDefault();const card=document.querySelectorAll('.recipe-card')[+ch.dataset.open];document.querySelectorAll('.recipe-card').forEach(c=>c.classList.remove('spotlight'));if(card){card.querySelector('details').open=true;card.classList.add('in','spotlight');card.scrollIntoView({behavior:'smooth',block:'start'})}}}));
  const fitHero=()=>{const h=document.querySelector('.hero');if(!h)return;const top=(document.querySelector('.concept-bar')?.offsetHeight||0)+(document.querySelector('.header')?.offsetHeight||0);const band=document.querySelector('.honey-band')?.offsetHeight||0;h.style.setProperty('--fit',(innerHeight-top-band)+'px');h.style.setProperty('--hdr',(document.querySelector('.header')?.offsetHeight||110)+'px');requestAnimationFrame(buildHoneyDrip)};fitHero();setTimeout(fitHero,250);setTimeout(fitHero,1200);document.fonts&&document.fonts.ready.then(fitHero);window.removeEventListener('resize',window.__fit||(()=>{}));window.__fit=fitHero;addEventListener('resize',fitHero);
  const t2=document.querySelector('[data-t2]');if(t2){const step=()=>(t2.querySelector('.tst2-card')?.offsetWidth||300)+22;document.querySelector('[data-t2-prev]').onclick=()=>t2.scrollBy({left:-step(),behavior:'smooth'});document.querySelector('[data-t2-next]').onclick=()=>t2.scrollBy({left:step(),behavior:'smooth'})}
  if(p==='recipes'&&openRecipe!=null){const card=document.querySelectorAll('.recipe-card')[openRecipe];if(card){card.querySelector('details').open=true;card.classList.add('in','spotlight');setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'start'}),60)}}
  openRecipe=null;
}
window.addEventListener('hashchange',render);render();
